package pipeline

// Integration tests: the full pipeline (hash → read-only open → parse → detect →
// audit) against the committed fixtures and, when present, the public benchmark
// datasets (fetched by scripts/fetch-datasets.sh, generated by make genbenign).
//
// Expected alert counts are ranges around the measured Phase 1 baseline
// (BASELINE.md): a change that moves a number outside its range is either a
// regression or an improvement that must be reflected in BASELINE.md.

import (
	"drishti-nexus/internal/config"
	"drishti-nexus/internal/models"
	"os"
	"path/filepath"
	"testing"
	"time"
)

var repoRoot = filepath.Join("..", "..")

func testConfig(t *testing.T) *models.Config {
	t.Helper()
	cfg, _, err := config.Load(filepath.Join(repoRoot, "configs", "config.yaml"))
	if err != nil {
		t.Fatal(err)
	}
	return cfg
}

func runFiles(t *testing.T, files ...string) *Result {
	t.Helper()
	res, err := Run(files, Options{Config: testConfig(t), Command: "test", ToolVersion: "test"})
	if err != nil {
		t.Fatal(err)
	}
	if err := res.Finish(&Options{}, "ok"); err != nil {
		t.Fatal(err)
	}
	return res
}

type span struct{ min, max int }

func (s span) has(n int) bool { return n >= s.min && n <= s.max }

func checkRange(t *testing.T, what string, got int, want span) {
	t.Helper()
	if !want.has(got) {
		t.Errorf("%s = %d, want %d..%d", what, got, want.min, want.max)
	}
}

func TestIntegration_SampleAuthFixture(t *testing.T) {
	res := runFiles(t, filepath.Join(repoRoot, "testdata", "fixtures", "sample_auth.log"))
	st := res.Stats
	if st.Lines != 21 || st.Entries != 21 || st.ParseQuality[models.QualityClean] != 21 {
		t.Errorf("lines=%d entries=%d quality=%v", st.Lines, st.Entries, st.ParseQuality)
	}
	want := map[string]int{
		"Authentication Brute Force":        1,
		"Excessive Authentication Failures": 1,
		"Injection Pattern Detected":        1,
		"Suspicious Command Execution":      1,
		"Time-based Anomaly":                1,
	}
	for rule, n := range want {
		if st.AlertsByRule[rule] != n {
			t.Errorf("%s: %d alerts, want %d (all: %v)", rule, st.AlertsByRule[rule], n, st.AlertsByRule)
		}
	}
	if len(st.AlertsByRule) != len(want) {
		t.Errorf("unexpected rules fired: %v", st.AlertsByRule)
	}
}

func TestIntegration_EdgeCaseFixture(t *testing.T) {
	res := runFiles(t, filepath.Join(repoRoot, "testdata", "fixtures", "edge_cases.log"))
	st := res.Stats
	if st.Lines != 24 || st.Entries != 14 {
		t.Errorf("lines=%d entries=%d, want 24 physical lines → 14 entries", st.Lines, st.Entries)
	}
	if st.ParseQuality[models.QualityClean] != 10 || st.ParseQuality[models.QualityPartial] != 3 || st.ParseQuality[models.QualityBestEffort] != 1 {
		t.Errorf("quality = %v", st.ParseQuality)
	}
	if st.ByParser["json"] != 2 || st.ByParser["apache"] != 1 || st.ByParser["generic"] != 1 {
		t.Errorf("parsers = %v", st.ByParser)
	}
	if st.Repairs["encoding_repaired"] != 2 || st.Repairs["timestamp_inherited"] != 1 {
		t.Errorf("repairs = %v", st.Repairs)
	}
	if st.AlertsByRule["Authentication Brute Force"] != 1 || st.AlertsByRule["Injection Pattern Detected"] != 1 {
		t.Errorf("alerts = %v", st.AlertsByRule)
	}
	for _, a := range res.Alerts() {
		if a.RuleName == "Authentication Brute Force" && len(a.RelatedLogs) != 4 {
			t.Errorf("brute force should cite 3 failures + the success: %v", a.RelatedLogs)
		}
	}
}

func TestIntegration_LogHubOpenSSH2kFixture(t *testing.T) {
	res := runFiles(t, filepath.Join(repoRoot, "testdata", "fixtures", "loghub_openssh_2k.log"))
	st := res.Stats
	if st.Entries != 2000 || st.ParseQuality[models.QualityClean] != 2000 {
		t.Errorf("entries=%d quality=%v", st.Entries, st.ParseQuality)
	}
	checkRange(t, "excessive failures", st.AlertsByRule["Excessive Authentication Failures"], span{12, 18})
	checkRange(t, "total alerts", st.Alerts, span{13, 20})
}

func TestIntegration_ChainOfCustody(t *testing.T) {
	src := filepath.Join(repoRoot, "testdata", "fixtures", "sample_auth.log")
	before, err := os.Stat(src)
	if err != nil {
		t.Fatal(err)
	}
	auditLog := filepath.Join(t.TempDir(), "audit.log")
	opts := Options{Config: testConfig(t), ConfigPath: filepath.Join(repoRoot, "configs", "config.yaml"),
		Command: "test", ToolVersion: "test", AuditLogPath: auditLog}
	res, err := Run([]string{src}, opts)
	if err != nil {
		t.Fatal(err)
	}
	if err := res.Finish(&opts, "ok"); err != nil {
		t.Fatal(err)
	}

	s := res.Session
	ev := s.Evidence[0]
	if len(ev.SHA256Before) != 64 || ev.SHA256After != ev.SHA256Before || ev.Unchanged == nil || !*ev.Unchanged {
		t.Errorf("evidence hashes: %+v", ev)
	}
	if len(s.Config.Rules) != 7 || s.Config.Rules[0].Threshold != 3 || s.Config.ConfigSHA256 == "" {
		t.Errorf("rule config not recorded: %+v", s.Config)
	}
	if s.OSUser == "" || s.ToolVersion != "test" || s.FinishedAt == nil || s.Results == nil || s.Results.Entries != 21 {
		t.Errorf("session incomplete: %+v", s)
	}
	after, _ := os.Stat(src)
	if !after.ModTime().Equal(before.ModTime()) || after.Size() != before.Size() {
		t.Error("source file metadata changed")
	}
}

// ── Public datasets (skipped when not fetched) ──

func datasetOrSkip(t *testing.T, rel string) string {
	t.Helper()
	p := filepath.Join(repoRoot, rel)
	if _, err := os.Stat(p); err != nil {
		t.Skipf("%s not present (run scripts/fetch-datasets.sh or make genbenign)", rel)
	}
	if testing.Short() {
		t.Skip("skipping dataset in -short mode")
	}
	return p
}

func TestIntegration_Datasets(t *testing.T) {
	tests := []struct {
		name       string
		path       string
		lines      int
		structured float64 // minimum Clean+Partial share
		alerts     span
		rules      map[string]span
	}{
		{
			name: "loghub-ssh", path: "testdata/datasets/loghub-ssh/SSH.log", lines: 655147, structured: 99.99,
			alerts: span{1500, 1950},
			rules: map[string]span{
				"Excessive Authentication Failures": {1450, 1900},
				"Authentication Brute Force":        {0, 5},
				"Privilege Escalation Indicator":    {0, 0},
			},
		},
		{
			name: "loghub-linux", path: "testdata/datasets/loghub-linux/Linux.log", lines: 25567, structured: 99.9,
			alerts: span{650, 900},
			rules: map[string]span{
				"Excessive Authentication Failures": {300, 400},
				"Injection Pattern Detected":        {0, 2},
			},
		},
		{
			name: "mordor-mimikatz", path: "testdata/datasets/mordor/empire_mimikatz_logonpasswords_2020-08-07103224.json", lines: 6026, structured: 100,
			alerts: span{1, 6},
			rules:  map[string]span{"Suspicious Command Execution": {1, 3}},
		},
		{
			name: "mordor-psexec", path: "testdata/datasets/mordor/empire_psexec_dcerpc_tcp_svcctl_2020-09-20121608.json", lines: 4348, structured: 100,
			alerts: span{3, 10},
			rules: map[string]span{
				"Suspicious Command Execution":      {2, 6},
				"Excessive Authentication Failures": {0, 0},
			},
		},
		{
			name: "synthetic-benign", path: "testdata/benign/auth_benign.log", lines: 50000, structured: 100,
			alerts: span{0, 100}, // every alert here is a false positive
			rules: map[string]span{
				"Privilege Escalation Indicator": {0, 0},
				"Authentication Brute Force":     {0, 0},
				"Injection Pattern Detected":     {0, 0},
				"Suspicious Command Execution":   {0, 0},
			},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			p := datasetOrSkip(t, tt.path)
			start := time.Now()
			res := runFiles(t, p)
			st := res.Stats
			t.Logf("%s: %d lines, %d alerts, %d incidents, %v, %v in %v", tt.name, st.Lines, st.Alerts, st.Incidents, st.ParseQuality, st.AlertsByRule, time.Since(start))

			if st.Lines != tt.lines {
				t.Errorf("lines = %d, want %d (dataset changed?)", st.Lines, tt.lines)
			}
			structured := float64(st.ParseQuality[models.QualityClean]+st.ParseQuality[models.QualityPartial]) * 100 / float64(st.Entries)
			if structured < tt.structured {
				t.Errorf("structured parse rate %.3f%% < %.3f%%", structured, tt.structured)
			}
			checkRange(t, "alerts", st.Alerts, tt.alerts)
			for rule, want := range tt.rules {
				checkRange(t, rule, st.AlertsByRule[rule], want)
			}
		})
	}
}
